import { process } from "../data/portfolio";
import { useScrollReveal } from "../hooks/useScrollReveal";
import { useTheme } from "../context/ThemeContext";

export default function Process() {
  const { ref, revealed } = useScrollReveal();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <section id="process" className={`py-28 border-t transition-colors duration-300
      ${isDark ? "bg-ink-950 border-wire" : "bg-paper-50 border-wire-light"}`}>
      <div className="max-w-6xl mx-auto px-6">
        <div className="mb-14">
          <p className="section-label mb-4">Process</p>
          <h2 className={`section-title text-3xl sm:text-4xl lg:text-5xl max-w-xl ${isDark ? "text-stone-200" : "text-gray-900"}`}>
            How a project<br />
            <span className={isDark ? "text-stone-500" : "text-gray-400"}>actually gets built.</span>
          </h2>
        </div>

        <div ref={ref} className={revealed ? "fade-up visible" : "fade-up"}>
          {/* Desktop */}
          <div className={`hidden lg:grid grid-cols-6 gap-px mb-px ${isDark ? "bg-wire" : "bg-wire-light"}`}>
            {process.map((step) => (
              <div key={step.step} className={`px-6 pt-6 pb-2 ${isDark ? "bg-ink-950" : "bg-paper-50"}`}>
                <span className={`font-mono text-xs tracking-widest ${isDark ? "text-stone-600" : "text-gray-400"}`}>
                  {step.step}
                </span>
              </div>
            ))}
          </div>
          <div className={`hidden lg:grid grid-cols-6 gap-px ${isDark ? "bg-wire" : "bg-wire-light"}`}>
            {process.map((step) => (
              <div key={step.step} className={`px-6 pb-8 pt-4 ${isDark ? "bg-ink-950" : "bg-paper-50"}`}>
                <h3 className={`font-display font-semibold text-sm mb-3 leading-snug ${isDark ? "text-stone-200" : "text-gray-900"}`}>
                  {step.title}
                </h3>
                <p className={`text-xs leading-relaxed ${isDark ? "text-stone-500" : "text-gray-500"}`}>
                  {step.description}
                </p>
              </div>
            ))}
          </div>

          {/* Mobile */}
          <div className={`lg:hidden border ${isDark ? "border-wire" : "border-wire-light"}`}>
            {process.map((step, i) => (
              <div key={step.step} className={`flex gap-6 p-6 ${i < process.length - 1 ? `border-b ${isDark ? "border-wire" : "border-wire-light"}` : ""}`}>
                <span className={`font-mono text-xs w-6 flex-shrink-0 mt-1 ${isDark ? "text-stone-600" : "text-gray-400"}`}>
                  {step.step}
                </span>
                <div>
                  <h3 className={`font-display font-semibold text-sm mb-2 ${isDark ? "text-stone-200" : "text-gray-900"}`}>
                    {step.title}
                  </h3>
                  <p className={`text-sm leading-relaxed ${isDark ? "text-stone-500" : "text-gray-500"}`}>
                    {step.description}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className={`mt-12 border p-6 transition-colors duration-300
          ${isDark ? "border-wire bg-ink-900" : "border-wire-light bg-paper-100"}`}>
          <p className={`font-mono text-xs leading-relaxed ${isDark ? "text-stone-500" : "text-gray-500"}`}>
            <span className="text-accent-glow">// note:</span> This process isn't rigid. Every project has different constraints. What stays constant is the order of thinking — design decisions before development decisions, always.
          </p>
        </div>
      </div>
    </section>
  );
}
